def subtotal(price: float, quantity: int) -> float:
    return price * quantity
print(subtotal(2.5, 4))

def display_name(name: str | None) -> str:
    return name if name is not None else 'Guest'
print(display_name(None))

def normalize_id(value: int | str) -> str:
    return str(value).strip()
print(normalize_id(42), normalize_id(' A7 '))

def area(width: float, height: float) -> float:
    return width * height
print(area.__annotations__['return'].__name__)
